function resolveTabGroupEdge(
  panelRect: Pick<DOMRect, "left" | "top" | "width" | "height">,
  bodyRect: Pick<DOMRect, "top" | "height"> | null,
  point: TabPointerDragPoint,
): PaneDropEdge | null {
  if (panelRect.width <= 0 || panelRect.height <= 0) return null;
  const localX = point.x - panelRect.left;
  const horizontalEdge = panelRect.width * 0.2;
  if (localX < horizontalEdge) return "left";
  if (localX > panelRect.width - horizontalEdge) return "right";

  const tabStripBottom = panelRect.top + TAB_GROUP_STRIP_HEIGHT_PX;
  if (point.y < tabStripBottom) return null;
  const bodyTop = bodyRect?.top ?? tabStripBottom;
  const bodyHeight = bodyRect?.height ?? Math.max(0, panelRect.height - TAB_GROUP_STRIP_HEIGHT_PX);
  if (bodyHeight <= 0) return null;
  const bodyLocalY = point.y - bodyTop;
  const verticalEdge = bodyHeight * 0.2;
  if (bodyLocalY < verticalEdge) return "top";
  if (bodyLocalY > bodyHeight - verticalEdge) return "bottom";
  return null;
}

function parseDraggedPane(value: string): DraggedPane | null {
  if (!value) return null;
  try {
    const parsed = JSON.parse(value) as Partial<DraggedPane>;
    if (typeof parsed.tabId === "string" && typeof parsed.leafId === "string") {
      return { tabId: parsed.tabId, leafId: parsed.leafId };
    }
  } catch {
    const separator = value.indexOf(":");
    if (separator > 0 && separator < value.length - 1) {
      return { tabId: value.slice(0, separator), leafId: value.slice(separator + 1) };
    }
  }
  return null;
}

