import { useEffect } from "react";

export type ShortcutActionId =
  | "tab.newTerminal"
  | "tab.newBrowser"
  | "tab.close"
  | "tab.next"
  | "tab.previous"
  | "tab.select1"
  | "tab.select2"
  | "tab.select3"
  | "tab.select4"
  | "workspace.select1"
  | "workspace.select2"
  | "workspace.select3"
  | "workspace.select4"
  | "terminal.splitRight"
  | "terminal.splitDown"
  | "terminal.unsplit"
  | "sidebar.left.toggle"
  | "commandPalette.open";

type ShortcutBinding = {
  key: string;
  mod?: boolean;
  control?: boolean;
  alt?: boolean;
  shift?: boolean;
};

export type ShortcutDefinition = {
  id: ShortcutActionId;
  title: string;
  group: "Tabs" | "Terminal Panes" | "Global" | "Workspaces";
  binding: ShortcutBinding;
  source: "original" | "ferryx";
};

